 */
class ReactionException : public std::runtime_error {
public:
    /**
     * @brief Error codes for different types of exceptions.
     */
    enum class ErrorCode {
        UNKNOWN = 0,
        DEPENDENCY_CYCLE,
        SELF_OBSERVATION,
