    // ==================== Compound Assignment Operators ====================

    /// @brief Compound addition assignment operator (+=)
    template <typename U>
        requires(IsVarExpr<Expr> && !ConstType<Type> && AddAssignable<Type, U>)
    React &operator+=(const U &rhs) {
        atomicAddAssign(*getPtr(), rhs);
        return *this;
