        REACTION_REGISTER_THREAD();
        getPtr()->close();
        return *this;
    }

    /// @brief Assign a human-readable name for debugging/tracing.
    React &setName(const std::string &name) {
        ObserverGraph::getInstance().setName(getPtr(), name);
