        if (m_observerList.contains(node)) {
            for (auto &ob : m_observerList.at(node).get()) {
                if (auto locked_ob = ob.lock()) {
                    if (m_dependentList.contains(locked_ob)) {
                        m_dependentList.at(locked_ob).erase(node);
                    }
