     *
     * @param f    Expression function/lambda.
     * @param args Additional arguments (usually reactive inputs).
     */
    template <typename F, HasArguments... A>
    void set(F &&f, A &&...args) {
        this->setSource(std::forward<F>(f), std::forward<A>(args)...);
        this->notify();
    }

