            return *reinterpret_cast<const Type*>(storage.buffer);
        } else {
            // Runtime branch for conditional_sbo types
            if (is_sbo_storage) {
                return *reinterpret_cast<const Type*>(storage.buffer);
            } else {
                return *storage.heap_ptr;
            }
        }
    }

