                *m_ptr = std::forward<T>(t);
            }
        }
        return changed;
    }

    /**
     * @brief Get the raw pointer to the managed resource.
     *
     * Throws std::runtime_error if the resource is not initialized.
     *
     * @return Type* Raw pointer to the resource.
