    [[nodiscard]] Type *getRawPtr() const {
        ConditionalSharedLock<ConditionalSharedMutex> lock(m_resourceMutex);
        if (!this->m_ptr) {
            REACTION_THROW_NULL_POINTER("resource pointer access");
        }
        return this->m_ptr.get();
    }

