template <typename Op, typename T>
    requires IsReact<std::remove_cvref_t<T>> || IsBinaryOpExpr<std::remove_cvref_t<T>> || IsUnaryOpExpr<std::remove_cvref_t<T>>
constexpr auto make_unary_op(T &&operand) {
