    using ValueType = std::decay_t<decltype(impl.get())>;
    ValueType oldValue{};

    impl.atomicOperation([&oldValue](auto &val) -> bool {
        oldValue = val;
        ++val;
        return true; // Increment always represents a change
    },
        true);
    return oldValue;
}

